#!/usr/bin/env bash
# Java (Spring Boot) vs Rust (Axum) benchmark on the same PostgreSQL and the same traffic mix.
#
# Per service: start it and time the health probe, 30 s warm-up, 60 s at a fixed request rate
# (CPU, latency, memory, DB queries, sampled every second), 30 s at fixed concurrency with no
# rate cap (peak throughput). Load is generated by k6 (grafana/k6 Docker image, host network),
# process metrics come from /proc/<pid> (utime+stime over all threads, VmRSS, VmHWM).
#
# Output (bench/results/):
#   summary.json      aggregate numbers per service (schema read by the frontend)
#   timeseries.json   per-second samples of the fixed-rate phase per service
#   run.log           the plain-text log of this script, one line per second during the runs
#   raw/              k6 summaries per phase, per-second aggregates, process metrics, service logs
#
# Requirements: Linux, docker (compose v2), cargo, java 17+ (./mvnw downloads Maven), python3, jq, curl, bc.
# Knobs (env): RATE=500 DURATION=60 WARMUP=30 PEAK_DURATION=30 CONCURRENCY=64 VCPU_HOUR_USD=0.0509
#              SKIP_BUILD=1 (reuse existing jar / binary)  SERVICES="java rust"  JAVA_OPTS=...
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
RESULTS_DIR="${SCRIPT_DIR}/results"
RAW_DIR="${RESULTS_DIR}/raw"
mkdir -p "${RAW_DIR}"
RUN_LOG="${RESULTS_DIR}/run.log"
: > "${RUN_LOG}"
exec > >(tee -a "${RUN_LOG}") 2>&1

RATE="${RATE:-500}"
DURATION="${DURATION:-60}"
WARMUP="${WARMUP:-30}"
PEAK_DURATION="${PEAK_DURATION:-30}"
CONCURRENCY="${CONCURRENCY:-64}"
VCPU_HOUR_USD="${VCPU_HOUR_USD:-0.0509}"
SERVICES="${SERVICES:-java rust}"
K6_IMAGE="${K6_IMAGE:-grafana/k6:0.54.0}"
PG_URL="${DATABASE_URL:-postgres://petclinic:petclinic@localhost:5432/petclinic}"
JAVA_PORT=9966
RUST_PORT=9977
CLK_TCK="$(getconf CLK_TCK)"
COMPOSE=(docker compose -f "${REPO_ROOT}/docker-compose.yml" --profile postgres)

log() { printf '[bench %s] %s\n' "$(date +%H:%M:%S)" "$*"; }
die() { log "ERROR: $*"; exit 1; }

for tool in docker cargo java python3 jq curl bc; do
  command -v "$tool" >/dev/null || die "$tool is required"
done
docker compose version >/dev/null 2>&1 || die "docker compose v2 is required"

psql_exec() { "${COMPOSE[@]}" exec -T postgres psql -U petclinic -d petclinic -At -c "$1"; }

# --------------------------------------------------------------------------- database
log "starting PostgreSQL (docker compose --profile postgres)"
"${COMPOSE[@]}" up -d postgres >/dev/null
"${REPO_ROOT}/rust-petclinic/scripts/init-db.sh" >/dev/null
PG_VERSION="$(psql_exec "SHOW server_version" | cut -d' ' -f1)"

PG_STAT=0
if [[ "$(psql_exec "SHOW shared_preload_libraries")" != *pg_stat_statements* ]]; then
  log "enabling pg_stat_statements (ALTER SYSTEM + container restart)"
  psql_exec "ALTER SYSTEM SET shared_preload_libraries = 'pg_stat_statements'" >/dev/null || true
  "${COMPOSE[@]}" restart postgres >/dev/null
  for _ in $(seq 1 30); do psql_exec "select 1" >/dev/null 2>&1 && break; sleep 1; done
fi
if psql_exec "CREATE EXTENSION IF NOT EXISTS pg_stat_statements" >/dev/null 2>&1 \
   && psql_exec "SELECT count(*) FROM pg_stat_statements" >/dev/null 2>&1; then
  PG_STAT=1
  log "pg_stat_statements available: DB queries per request will be measured"
else
  log "pg_stat_statements unavailable: dbQueriesPerRequest omitted"
fi

# --------------------------------------------------------------------------- builds
JAVA_JAR="$(ls "${REPO_ROOT}"/target/spring-petclinic-rest-*.jar 2>/dev/null | grep -v '\.original$' | head -1 || true)"
RUST_BIN="${REPO_ROOT}/rust-petclinic/target/release/rust-petclinic"
if [[ " ${SERVICES} " == *" java "* && ( "${SKIP_BUILD:-0}" != "1" || -z "${JAVA_JAR}" ) ]]; then
  # ./mvnw honours MVNW_REPOURL and ~/.m2/settings.xml mirrors when Maven Central rate-limits the host.
  log "building Java jar (./mvnw -q -DskipTests package)"
  (cd "${REPO_ROOT}" && ./mvnw -q -DskipTests package)
  JAVA_JAR="$(ls "${REPO_ROOT}"/target/spring-petclinic-rest-*.jar | grep -v '\.original$' | head -1)"
fi
if [[ " ${SERVICES} " == *" rust "* && ( "${SKIP_BUILD:-0}" != "1" || ! -x "${RUST_BIN}" ) ]]; then
  log "building Rust binary (cargo build --release)"
  (cd "${REPO_ROOT}/rust-petclinic" && cargo build --release --quiet)
fi

log "pulling ${K6_IMAGE}"
docker pull -q "${K6_IMAGE}" >/dev/null

# --------------------------------------------------------------------------- helpers
SERVICE_PID=""
cleanup() {
  if [[ -n "${SERVICE_PID}" ]] && kill -0 "${SERVICE_PID}" 2>/dev/null; then
    kill "${SERVICE_PID}" 2>/dev/null || true
    wait "${SERVICE_PID}" 2>/dev/null || true
  fi
}
trap cleanup EXIT

now() { date +%s.%N; }

cpu_seconds() {  # utime + stime of the process (all threads), in seconds
  local stat; stat="$(cat "/proc/$1/stat")"
  stat="${stat##*) }"
  # shellcheck disable=SC2086
  set -- $stat
  echo "scale=3; (${12} + ${13}) / ${CLK_TCK}" | bc
}

peak_rss_mb() {  # VmHWM (peak resident set size), in MiB
  awk '/VmHWM/ { printf "%.1f", $2 / 1024 }' "/proc/$1/status"
}

wait_healthy() {  # <url> ; prints seconds until the health probe answers 200
  local url="$1" start; start="$(now)"
  for _ in $(seq 1 2400); do
    if curl -fs -o /dev/null "${url}/actuator/health"; then
      echo "scale=3; $(now) - ${start}" | bc; return 0
    fi
    sleep 0.05
  done
  die "service at ${url} did not become healthy"
}

k6_cmd() {  # <base-url> <k6-phase: fixed|peak> <duration> <summary-file-in-container> [extra args...]
  local base="$1" phase="$2" duration="$3" summary="$4"; shift 4
  docker run --rm -i --network host --user "$(id -u):$(id -g)" -v "${RAW_DIR}:/results" \
    -e BASE_URL="${base}" -e PHASE="${phase}" -e RATE="${RATE}" -e DURATION="${duration}" \
    -e VUS="${CONCURRENCY}" -e SUMMARY_FILE="${summary}" \
    "${K6_IMAGE}" run --quiet --no-color "$@" - < "${SCRIPT_DIR}/k6/mix.js"
}

run_k6() {  # <service> <phase> <base-url> <duration> ; k6 summary -> raw/<service>-<phase>.json
  local service="$1" phase="$2" base="$3" duration="$4"
  local k6_phase="fixed"
  [[ "$phase" == "peak" ]] && k6_phase="peak"
  k6_cmd "$base" "$k6_phase" "$duration" "/results/${service}-${phase}.json"
}

run_k6_sampled() {  # <service> <phase> <base-url> <duration> <pid> ; also per-second samples
  local service="$1" phase="$2" base="$3" duration="$4" pid="$5"
  local k6_phase="fixed"
  [[ "$phase" == "peak" ]] && k6_phase="peak"
  k6_cmd "$base" "$k6_phase" "$duration" "/results/${service}-${phase}.json" --out json=/dev/stdout \
    | python3 "${SCRIPT_DIR}/k6/aggregate.py" --service "$service" --pid "$pid" --duration "$duration" \
        --out "${RAW_DIR}/${service}-${phase}-per-second.json"
}

reset_pg_stat() { if [[ "$PG_STAT" == 1 ]]; then psql_exec "SELECT pg_stat_statements_reset()" >/dev/null; fi; }
pg_calls() {
  if [[ "$PG_STAT" == 1 ]]; then
    psql_exec "SELECT coalesce(sum(calls),0) FROM pg_stat_statements WHERE query NOT ILIKE '%pg_stat_statements%'"
  else
    echo null
  fi
}

reset_data() {  # remove owners created by previous runs so both services see the same data
  psql_exec "DELETE FROM owners WHERE last_name IN ('Loadtest','Check') AND id NOT IN (SELECT owner_id FROM pets)" >/dev/null
}

bench_service() {  # <service>
  local service="$1" base pid startup cpu0 cpu1 calls rss_fixed rss_peak
  case "$service" in
    java)
      [[ -n "$JAVA_JAR" ]] || die "Java jar not found under target/"
      base="http://localhost:${JAVA_PORT}/petclinic"
      log "starting Java: java ${JAVA_OPTS:-} -jar $(basename "$JAVA_JAR") --spring.profiles.active=postgres,spring-data-jpa"
      # shellcheck disable=SC2086
      java ${JAVA_OPTS:-} -jar "$JAVA_JAR" --spring.profiles.active=postgres,spring-data-jpa \
        > "${RAW_DIR}/java-service.log" 2>&1 &
      ;;
    rust)
      base="http://localhost:${RUST_PORT}/petclinic"
      log "starting Rust: ${RUST_BIN#"${REPO_ROOT}/"}"
      DATABASE_URL="${PG_URL}" PORT="${RUST_PORT}" RUST_LOG="${RUST_LOG:-warn}" "${RUST_BIN}" \
        > "${RAW_DIR}/rust-service.log" 2>&1 &
      ;;
    *) die "unknown service $service" ;;
  esac
  pid=$!; SERVICE_PID="$pid"
  startup="$(wait_healthy "$base")"
  log "${service}: healthy after ${startup}s (pid ${pid})"

  log "${service}: warm-up ${WARMUP}s @ ${RATE} req/s"
  run_k6 "$service" warmup "$base" "$WARMUP"

  reset_pg_stat
  cpu0="$(cpu_seconds "$pid")"
  log "${service}: fixed rate ${DURATION}s @ ${RATE} req/s"
  run_k6_sampled "$service" fixed "$base" "$DURATION" "$pid"
  cpu1="$(cpu_seconds "$pid")"
  calls="$(pg_calls)"
  rss_fixed="$(peak_rss_mb "$pid")"

  log "${service}: peak ${PEAK_DURATION}s @ ${CONCURRENCY} connections, no rate cap"
  run_k6_sampled "$service" peak "$base" "$PEAK_DURATION" "$pid"
  rss_peak="$(peak_rss_mb "$pid")"

  kill "$pid"; wait "$pid" 2>/dev/null || true; SERVICE_PID=""

  jq -n \
    --arg service "$service" --argjson startupSeconds "$startup" \
    --argjson cpuSecondsFixed "$(echo "$cpu1 - $cpu0" | bc)" \
    --argjson fixedRequests "$(jq '.metrics.http_reqs.values.count' "${RAW_DIR}/${service}-fixed.json")" \
    --argjson dbCalls "$calls" --argjson rssFixedMb "$rss_fixed" --argjson rssPeakMb "$rss_peak" \
    '{service: $service, startupSeconds: $startupSeconds, cpuSecondsFixed: $cpuSecondsFixed,
      fixedRequests: $fixedRequests, dbCallsFixed: $dbCalls, peakRssFixedMb: $rssFixedMb, peakRssPeakMb: $rssPeakMb}' \
    > "${RAW_DIR}/${service}-process.json"
  log "${service}: done"
}

# --------------------------------------------------------------------------- run
for service in $SERVICES; do
  reset_data
  bench_service "$service"
done
reset_data

# --------------------------------------------------------------------------- summary.json
HOST="$(lscpu | awk -F: '/Model name/ { gsub(/^ +/, "", $2); print $2 }'), $(nproc) cores"
MEASURED_AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)"

service_json() {  # <service> <label>
  local service="$1" label="$2"
  local proc="${RAW_DIR}/${service}-process.json" fixed="${RAW_DIR}/${service}-fixed.json" peak="${RAW_DIR}/${service}-peak.json"
  [[ -f "$proc" && -f "$fixed" && -f "$peak" ]] || { echo null; return; }
  jq -n --arg lbl "$label" --argjson duration "$DURATION" --argjson vcpu "$VCPU_HOUR_USD" \
    --slurpfile proc "$proc" --slurpfile fixed "$fixed" --slurpfile peak "$peak" '
    ($proc[0]) as $p | ($fixed[0].metrics) as $f | ($peak[0].metrics) as $k |
    ($p.cpuSecondsFixed / $p.fixedRequests * 1000000) as $cpuPerM |
    {
      "label": $lbl,
      cpuCoresAtFixedRate: (($p.cpuSecondsFixed / $duration) * 1000 | round / 1000),
      cpuSecondsPerMillionRequests: ($cpuPerM | round),
      costPerMillionRequestsUsd: (($cpuPerM / 3600 * $vcpu) * 10000 | round / 10000),
      peakRequestsPerSecond: ($k.http_reqs.values.rate | round),
      p50Ms: ($f.http_req_duration.values["p(50)"] * 10 | round / 10),
      p99Ms: ($f.http_req_duration.values["p(99)"] * 10 | round / 10),
      memoryMb: ($p.peakRssPeakMb | round),
      startupSeconds: ($p.startupSeconds * 100 | round / 100),
      failedRequests: (($f.http_req_failed.values.passes // 0) + ($k.http_req_failed.values.passes // 0)),
      achievedRequestsPerSecond: ($f.http_reqs.values.rate * 10 | round / 10),
      droppedIterationsAtFixedRate: ($f.dropped_iterations.values.count // 0),
      peakP50Ms: ($k.http_req_duration.values["p(50)"] * 10 | round / 10),
      peakP99Ms: ($k.http_req_duration.values["p(99)"] * 10 | round / 10),
      memoryAtFixedRateMb: ($p.peakRssFixedMb | round)
    }
    + (if $p.dbCallsFixed != null then { dbQueriesPerRequest: ($p.dbCallsFixed / $p.fixedRequests * 10 | round / 10) } else {} end)'
}

jq -n \
  --arg measuredAt "$MEASURED_AT" --arg host "$HOST" --argjson vcpu "$VCPU_HOUR_USD" \
  --argjson rate "$RATE" --argjson duration "$DURATION" --argjson warmup "$WARMUP" \
  --argjson peakDuration "$PEAK_DURATION" --argjson conc "$CONCURRENCY" \
  --argjson java "$(service_json java 'Java — Spring Boot')" --argjson rust "$(service_json rust 'Rust — Axum')" \
  --arg loadTool "k6 (${K6_IMAGE})" --arg db "postgres ${PG_VERSION}" \
  '{
    measuredAt: $measuredAt,
    host: $host,
    runs: 1,
    vcpuHourUsd: $vcpu,
    loadTool: $loadTool,
    db: $db,
    workload: {
      ratePerSecond: $rate, durationSeconds: $duration, warmupSeconds: $warmup,
      peakConcurrency: $conc, peakDurationSeconds: $peakDuration,
      mix: "40% owner lookup, 20% owner search, 15% vets, 10% pet types, 10% pet lookup, 5% create owner"
    },
    services: ({} + (if $java != null then {java: $java} else {} end) + (if $rust != null then {rust: $rust} else {} end))
  }' > "${RESULTS_DIR}/summary.json"

# --------------------------------------------------------------------------- timeseries.json
timeseries_service() {  # <service> <label>
  local service="$1" label="$2"
  local fixed="${RAW_DIR}/${service}-fixed-per-second.json" peak="${RAW_DIR}/${service}-peak-per-second.json"
  [[ -f "$fixed" && -f "$peak" ]] || { echo null; return; }
  jq -n --arg lbl "$label" --slurpfile fixed "$fixed" --slurpfile peak "$peak" \
    '{"label": $lbl, samples: $fixed[0].samples, peakSamples: $peak[0].samples}'
}

jq -n \
  --arg measuredAt "$MEASURED_AT" --arg host "$HOST" --arg db "postgres ${PG_VERSION}" \
  --argjson rate "$RATE" --argjson duration "$DURATION" --argjson peakDuration "$PEAK_DURATION" --argjson conc "$CONCURRENCY" \
  --argjson java "$(timeseries_service java 'Spring Boot 4 / Tomcat')" --argjson rust "$(timeseries_service rust 'Axum / sqlx')" \
  --slurpfile summary "${RESULTS_DIR}/summary.json" '
  def brief(s): if s == null then null else {cpuCores: s.cpuCoresAtFixedRate, p50Ms: s.p50Ms, p99Ms: s.p99Ms, rssMb: s.memoryMb, peakRps: s.peakRequestsPerSecond, startupSeconds: s.startupSeconds} end;
  {
    measuredAt: $measuredAt, host: $host, db: $db,
    ratePerSecond: $rate, durationSeconds: $duration, peakDurationSeconds: $peakDuration, peakConcurrency: $conc,
    services: ({} + (if $java != null then {java: $java} else {} end) + (if $rust != null then {rust: $rust} else {} end)),
    summary: ({} + (if $summary[0].services.java then {java: brief($summary[0].services.java)} else {} end)
                 + (if $summary[0].services.rust then {rust: brief($summary[0].services.rust)} else {} end))
  }' > "${RESULTS_DIR}/timeseries.json"

log "written: ${RESULTS_DIR#"${REPO_ROOT}/"}/summary.json, timeseries.json, run.log, raw/"
jq -r '
  def row(k; v): [k, (.services.java[v] // "-" | tostring), (.services.rust[v] // "-" | tostring)] | @tsv;
  (["metric", "java", "rust"] | @tsv),
  row("CPU cores @ fixed rate"; "cpuCoresAtFixedRate"),
  row("CPU s / 1M requests"; "cpuSecondsPerMillionRequests"),
  row("USD / 1M requests"; "costPerMillionRequestsUsd"),
  row("peak req/s"; "peakRequestsPerSecond"),
  row("p50 ms"; "p50Ms"), row("p99 ms"; "p99Ms"),
  row("peak RSS MB"; "memoryMb"), row("startup s"; "startupSeconds"),
  row("DB queries / request"; "dbQueriesPerRequest"), row("failed requests"; "failedRequests")
' "${RESULTS_DIR}/summary.json" | column -t -s $'\t'
